# PTX source for MSE mean reduction (fp16 inputs, fp16 scalar output)
PTX_SOURCE = r'''
.version 7.0
.target sm_80
.address_size 64

.visible .entry mse_kernel(
    .param .u64 pred_ptr,
    .param .u64 targ_ptr,
    .param .u64 out_ptr,
    .param .u32 n_elements
)
{
    // -------------------------------------------------
    // registers
    // -------------------------------------------------
    .reg .u64 %pred, %targ, %out;
    .reg .u32 %n;
    .reg .u32 %tid;
    .reg .u32 %i;
    .reg .pred %p;

    .reg .f16 %a, %b;
    .reg .f32 %fa, %fb, %diff, %sum, %tmp;
    .reg .u64 %addr_a, %addr_b, %offset64;
    .reg .u64 %shm_off, %shm_off2;
    .reg .u32 %stride;

    // -------------------------------------------------
    // load kernel parameters
    // -------------------------------------------------
    ld.param.u64 %pred, [pred_ptr];
    ld.param.u64 %targ, [targ_ptr];
    ld.param.u64 %out,  [out_ptr];
    ld.param.u32 %n,    [n_elements];

    // -------------------------------------------------
    // thread id within the single block
    // -------------------------------------------------
    mov.u32 %tid, %tid.x;          // blockDim.x == 1024, gridDim.x == 1

    // -------------------------------------------------
    // each thread accumulates a partial sum
    // -------------------------------------------------
    mov.f32 %sum, 0f00000000;      // sum = 0.0f

    mov.u32 %i, %tid;              // i = threadIdx.x
LOOP_START:
    setp.ge.u32 %p, %i, %n;        // if i >= N break
    @%p bra LOOP_END;

    // address = base + i * sizeof(half) (2 bytes)
    mul.wide.u32 %offset64, %i, 2;
    add.u64 %addr_a, %pred, %offset64;
    ld.global.f16 %a, [%addr_a];
    add.u64 %addr_b, %targ, %offset64;
    ld.global.f16 %b, [%addr_b];

    // convert to fp32
    cvt.rn.f32.f16 %fa, %a;
    cvt.rn.f32.f16 %fb, %b;

    // (a-b)^2
    sub.f32 %diff, %fa, %fb;
    mul.f32 %diff, %diff, %diff;

    // accumulate
    add.f32 %sum, %sum, %diff;

    // i += blockDim.x (1024)
    add.u32 %i, %i, 1024;
    bra LOOP_START;
LOOP_END:

    // -------------------------------------------------
    // block-wide reduction using shared memory
    // -------------------------------------------------
    .shared .align 4 .f32 shm[1024];

    // store partial sum
    mul.wide.u32 %shm_off, %tid, 4;          // offset in bytes
    st.shared.f32 [%shm_off], %sum;
    bar.sync 0;

    // reduction loop: stride = 512,256,...,1
    mov.u32 %stride, 512;
REDUCTION_LOOP:
    setp.eq.u32 %p, %stride, 0;
    @%p bra REDUCTION_DONE;

    setp.lt.u32 %p, %tid, %stride;
    @%p {
        // load my value
        ld.shared.f32 %tmp, [%shm_off];
        // load partner value
        mul.wide.u32 %shm_off2, %tid, 4;
        add.u64 %shm_off2, %shm_off2, %stride;
        shl.b64 %shm_off2, %shm_off2, 2;   // multiply by 4 to get byte offset
        ld.shared.f32 %sum, [%shm_off2];
        // add
        add.f32 %tmp, %tmp, %sum;
        // store back
        st.shared.f32 [%shm_off], %tmp;
    }
    bar.sync 0;
    shr.u32 %stride, %stride, 1;
    bra REDUCTION_LOOP;
REDUCTION_DONE:

    // -------------------------------------------------
    // thread 0 writes the final mean (fp16) to output
    // -------------------------------------------------
    setp.eq.u32 %p, %tid, 0;
    @%p {
        // load block sum (now total sum)
        ld.shared.f32 %sum, [0];
        // convert N to fp32
        cvt.rn.f32.u32 %tmp, %n;
        // mean = sum / N
        div.f32 %sum, %sum, %tmp;
        // cast to half
        cvt.rn.f16.f32 %a, %sum;
        // store result
        st.global.f16 [%out], %a;
    }
    ret;
}
'''

# -------------------------------------------------
# Python wrapper that loads and launches the PTX kernel
# -------------------------------------------------
import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.ptx_module = ptx_load(PTX_SOURCE)

    def forward(self, predictions: torch.Tensor, targets: torch.Tensor) -> torch.Tensor:
        # allocate scalar output (fp16)
        out = torch.empty((), dtype=torch.float16, device=predictions.device)

        # total number of elements
        n_elements = predictions.numel()

        # launch configuration: 1 block, 1024 threads
        grid  = (1, 1, 1)
        block = (1024, 1, 1)

        # arguments: pointers and element count
        args = [
            predictions.data_ptr(),
            targets.data_ptr(),
            out.data_ptr(),
            n_elements
        ]

        ptx_launch(self.ptx_module, "mse_kernel", grid, block, args)
        return out
